<?php
declare(strict_types=1);use Vendi\Database\Connection;use Vendi\Http\ApiGuard;use Vendi\Auth\UserService;
require dirname(__DIR__,3).'/vendor/autoload.php';session_start();header('Content-Type: application/json; charset=utf-8');
try{$u=ApiGuard::session();$db=Connection::make(['host'=>getenv('DB_HOST')?:'127.0.0.1','port'=>(int)(getenv('DB_PORT')?:3306),'database'=>getenv('DB_DATABASE')?:'vendi','username'=>getenv('DB_USERNAME')?:'root','password'=>getenv('DB_PASSWORD')?:'']);ApiGuard::permission($db,$u,'users.manage');$s=new UserService($db);if($_SERVER['REQUEST_METHOD']==='GET'){if(isset($_GET['user_id']))echo json_encode(['ok'=>true,'permissions'=>$s->userPermissions((int)$u['business_id'],(int)$_GET['user_id'])],JSON_UNESCAPED_UNICODE);elseif(isset($_GET['list']))echo json_encode(['ok'=>true,'users'=>$s->users((int)$u['business_id'])],JSON_UNESCAPED_UNICODE);elseif(isset($_GET['role_id']))echo json_encode(['ok'=>true,'permissions'=>$s->permissionsForRole((int)$u['business_id'],(int)$_GET['role_id'])],JSON_UNESCAPED_UNICODE);else echo json_encode(['ok'=>true,'roles'=>$s->roles((int)$u['business_id'])],JSON_UNESCAPED_UNICODE);exit;}ApiGuard::csrf();$d=json_decode(file_get_contents('php://input'),true,512,JSON_THROW_ON_ERROR);if(($d['action']??'create')==='status'){$s->setStatus((int)$u['business_id'],(int)$d['user_id'],(string)$d['status'],(int)$u['id']);echo json_encode(['ok'=>true]);exit;}if(($d['action']??'create')==='password'){$s->resetPassword((int)$u['business_id'],(int)$d['user_id'],(string)($d['password']??''),(int)$u['id']);echo json_encode(['ok'=>true]);exit;}if(($d['action']??'create')==='permissions'){$s->updatePermissions((int)$u['business_id'],(int)$d['user_id'],$d['permissions']??[]);echo json_encode(['ok'=>true]);exit;}$id=$s->create((int)$u['business_id'],(int)($d['branch_id']??$u['default_branch_id']),$d);echo json_encode(['ok'=>true,'user_id'=>$id]);}catch(Throwable$e){http_response_code(in_array((int)$e->getCode(),[401,403],true)?(int)$e->getCode():422);echo json_encode(['ok'=>false,'error'=>$e->getMessage()],JSON_UNESCAPED_UNICODE);}